package dev.industrialtechnology.railway;
import java.util.*;import net.minecraft.entity.*;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.world.World;import net.minecraft.item.*;import net.minecraft.nbt.*;import net.minecraft.init.Items;import net.minecraft.util.*;import cpw.mods.fml.common.registry.IEntityAdditionalSpawnData;import io.netty.buffer.ByteBuf;import dev.industrialtechnology.core.*;import dev.industrialtechnology.expansion.ExpansionConfig;
/** One authoritative body per vehicle. Consist members independently integrate the same rail distance. */
public final class EntityRollingStock extends Entity implements IEntityAdditionalSpawnData {
 public StockType stock=StockType.STEAM;public UUID owner,front,rear;public TrackWorld.Cursor rail;public final LogicalCargo cargo=new LogicalCargo(3,false),fuel=new LogicalCargo(1,true);public double speed,travel,throttle,brake=1,temperature=20;public int energy,water,burn;public boolean lights;public String status="PARKED";public final RailwayTickets tickets=new RailwayTickets(this);private long movedAt=Long.MIN_VALUE,chargeTick=Long.MIN_VALUE,inputTick=Long.MIN_VALUE,hornAt=Long.MIN_VALUE;private int chargeUsed;private double targetX,targetY,targetZ,targetYaw,targetPitch;private int interpolation;public double previousTravel;private int soundClock;private boolean ticketReady=true;private double routeLimit=1;
 public EntityRollingStock(World w){super(w);setSize(3,4);preventEntitySpawning=true;ignoreFrustumCheck=true;renderDistanceWeight=8;}
 public EntityRollingStock(World w,StockType type,TrackWorld.Cursor cursor,UUID owner){this(w);stock=type;this.owner=owner;rail=cursor;pose();sync();}
 @Override protected void entityInit(){dataWatcher.addObject(20,0);dataWatcher.addObject(21,0f);dataWatcher.addObject(22,0f);dataWatcher.addObject(23,0);dataWatcher.addObject(24,0f);dataWatcher.addObject(25,0);}
 public int capacity(){return ExpansionConfig.trainCapacity*(stock==StockType.AZ8A?2:1);}public int charge(int request,boolean simulate){if(!stock.electric()||request<=0)return 0;long tick=worldObj.getTotalWorldTime();if(chargeTick!=tick){chargeTick=tick;chargeUsed=0;}int n=Math.max(0,Math.min(request,Math.min(capacity()-energy,ExpansionConfig.chargeRate-chargeUsed)));if(!simulate){energy+=n;chargeUsed+=n;}return n;}
 public boolean permitted(EntityPlayer p){return p!=null&&(owner==null||owner.equals(p.getUniqueID())||p.capabilities.isCreativeMode);}
 public List<EntityRollingStock> consist(){List<EntityRollingStock> list=new ArrayList<>();Set<UUID> seen=new HashSet<>();EntityRollingStock e=this;while(e!=null&&seen.add(e.getUniqueID())&&list.size()<=ExpansionConfig.maxWagons){list.add(e);e=RailwayWorld.get(worldObj,e.rear);}return list;}
 public double cargoMass(){return cargo.mass()+fuel.mass();}public double totalMass(){double m=0;for(EntityRollingStock e:consist())m+=e.stock.mass+e.cargoMass();return m;}
 public boolean coupledComplete(){for(EntityRollingStock e:consist())if(e.rear!=null&&RailwayWorld.get(worldObj,e.rear)==null)return false;return true;}
 @Override public void onUpdate(){super.onUpdate();previousTravel=travel;if(worldObj.isRemote){stock=StockType.safe(dataWatcher.getWatchableObjectInt(20));speed=dataWatcher.getWatchableObjectFloat(21);double observedTravel=dataWatcher.getWatchableObjectFloat(22);travel=speed<.0001?observedTravel:Math.abs(observedTravel-travel)>3?observedTravel:travel+speed+(observedTravel-travel)*.15;energy=dataWatcher.getWatchableObjectInt(23);temperature=dataWatcher.getWatchableObjectFloat(24);lights=dataWatcher.getWatchableObjectInt(25)!=0;if(interpolation>0){double n=interpolation;setPosition(posX+(targetX-posX)/n,posY+(targetY-posY)/n,posZ+(targetZ-posZ)/n);rotationYaw+=(float)(MathHelper.wrapAngleTo180_double(targetYaw-rotationYaw)/n);rotationPitch+=(targetPitch-rotationPitch)/n;interpolation--;}updateBounds();clientEffects();return;}
  if(movedAt==worldObj.getTotalWorldTime())return;if(front!=null){speed=0;status=RailwayWorld.get(worldObj,front)==null?"WAITING FOR COUPLED VEHICLE":"COUPLED";sync();return;}if(!stock.engine()){speed=0;sync();return;}if(rail==null||rail.path(worldObj)==null){speed=0;status="TRACK UNLOADED / MISSING";sync();return;}List<EntityRollingStock> train=consist();if(!coupledComplete()){speed=0;status="COUPLED WAGON UNLOADED";sync();return;}if(ticksExisted%10==0)ticketReady=tickets.update(train);if(!ticketReady){speed=0;status="CHUNK TICKET LIMIT";sync();return;}
  boolean powered=stock.electric()?energy>0:steam();RailPath path=rail.path(worldObj);if(ticksExisted%5==0)routeLimit=lookAhead();double mass=totalMass(),limit=Math.min(stock.speed,Math.min(routeLimit,Math.min(ExpansionConfig.speed,path.speedLimit())));double effectiveBrake=speed>limit*.99&&speed>.02?Math.max(brake,1):brake;TileTrack t=TrackWorld.get(worldObj,rail.track);if(t!=null&&t.station&&worldObj.isBlockIndirectlyGettingPowered(t.xCoord,t.yCoord,t.zCoord)&&rail.s>6&&rail.s<10){brake=1;throttle=0;}
  TrainPhysics.Step step=TrainPhysics.tick(speed,mass,stock.traction*(stock==StockType.STEAM?pressure():1),throttle,effectiveBrake,path.grade()*rail.direction,limit,powered);int cost=(int)Math.min(Integer.MAX_VALUE,Math.ceil(step.work/20));if(stock.electric()&&cost>energy){step=TrainPhysics.tick(speed,mass,stock.traction,0,effectiveBrake,path.grade()*rail.direction,limit,false);cost=0;}
  double distance=step.speed;List<TrackWorld.Cursor> next=new ArrayList<>();boolean safe=true;for(EntityRollingStock e:train){TrackWorld.Cursor c=e.rail==null?null:e.rail.copy();if(c==null||!c.move(worldObj,distance)||!e.safeAt(c)){safe=false;break;}next.add(c);}if(safe&&collisionAhead(train,distance))safe=false;
  if(!safe){for(EntityRollingStock e:train){e.speed=0;e.sync();}speed=0;status="STOP: TRACK END / OBSTRUCTION / UNLOADED";sync();return;}
  if(stock.electric())energy-=cost;else if(distance>0&&throttle>0){water=Math.max(0,water-(int)Math.ceil(2+step.work/50000));temperature=Math.max(20,temperature-step.work/1000000);}status=!powered?stock.electric()?"NO RF":"WARMING / NEED FUEL OR WATER":brake>.5?"BRAKING":throttle>0?"TRACTION":"COASTING";
  for(int i=0;i<train.size();i++){EntityRollingStock e=train.get(i);e.rail=next.get(i);e.speed=step.speed;e.travel+=distance;e.movedAt=worldObj.getTotalWorldTime();e.pose();e.sync();}
 }
 private double lookAhead(){double allowed=ExpansionConfig.speed;for(int d=4;d<=64;d+=4){TrackWorld.Cursor c=rail.copy();boolean exists=c.move(worldObj,d);double target=exists?c.path(worldObj).speedLimit():0;double distance=Math.max(0,d-stock.length/2-2);allowed=Math.min(allowed,Math.sqrt(target*target*400+2*1.4*distance)/20);if(!exists)break;}return allowed;}
 private boolean steam(){if(burn<=0&&throttle>0&&temperature<295&&water>0&&fuel.count(0)>0){fuel.extract(0,1,false);burn=1600;}if(burn>0){burn--;temperature=Math.min(300,temperature+.35);}else temperature=Math.max(20,temperature-.12);if(throttle>0&&speed>0)temperature=Math.max(20,temperature-throttle*.08);return pressure()>.05&&water>0;}
 public double pressure(){return Math.max(0,Math.min(1,(temperature-100)/200));}
 public boolean safeAt(TrackWorld.Cursor c){double[] center=c.point(worldObj);if(center==null)return false;for(double offset:new double[]{-stock.length/2,0,stock.length/2}){TrackWorld.Cursor q=c.copy();if(!q.move(worldObj,offset))return false;double[] p=q.point(worldObj);int cx=MathHelper.floor_double(p[0]),cy=MathHelper.floor_double(p[1]),cz=MathHelper.floor_double(p[2]);for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){if(!worldObj.getChunkProvider().chunkExists((cx+dx)>>4,(cz+dz)>>4))return false;for(int dy=1;dy<=3;dy++){net.minecraft.block.Block b=worldObj.getBlock(cx+dx,cy+dy,cz+dz);if(b.getMaterial().blocksMovement()&&b!=RailwayRegistry.anchor)return false;}}}return true;}
 private boolean collisionAhead(List<EntityRollingStock> own,double d){TrackWorld.Cursor p=rail.copy();if(!p.move(worldObj,stock.length/2+1+d))return false;double[] a=p.point(worldObj);for(Object o:worldObj.getEntitiesWithinAABB(EntityRollingStock.class,AxisAlignedBB.getBoundingBox(a[0]-2,a[1]-1,a[2]-2,a[0]+2,a[1]+4,a[2]+2))){EntityRollingStock e=(EntityRollingStock)o;if(!own.contains(e))return true;}return false;}
 private void updateBounds(){if(stock==null)return;double a=Math.toRadians(rotationYaw),hx=Math.abs(Math.sin(a))*stock.length/2+Math.abs(Math.cos(a))*1.5,hz=Math.abs(Math.cos(a))*stock.length/2+Math.abs(Math.sin(a))*1.5;boundingBox.setBounds(posX-hx,posY,posZ-hz,posX+hx,posY+4.8,posZ+hz);}
 @Override public void setPosition(double x,double y,double z){super.setPosition(x,y,z);updateBounds();}
 public void pose(){if(rail==null||rail.path(worldObj)==null)return;double[] p=rail.point(worldObj);setPosition(p[0],p[1],p[2]);rotationYaw=(float)rail.yaw(worldObj);rotationPitch=(float)-Math.toDegrees(Math.atan(rail.path(worldObj).grade()*rail.direction));updateBounds();}
 private void sync(){dataWatcher.updateObject(20,stock.ordinal());dataWatcher.updateObject(21,(float)speed);dataWatcher.updateObject(22,(float)travel);dataWatcher.updateObject(23,energy);dataWatcher.updateObject(24,(float)temperature);dataWatcher.updateObject(25,lights?1:0);}
 private void clientEffects(){if(stock==StockType.STEAM&&temperature>110&&ticksExisted%4==0){double a=Math.toRadians(rotationYaw),x=posX-Math.sin(a)*7,z=posZ+Math.cos(a)*7;worldObj.spawnParticle("smoke",x,posY+4.2,z,0,.04,0);if(speed>.01&&ticksExisted%12==0)worldObj.spawnParticle("cloud",x,posY+.8,z,0,.02,0);}if(++soundClock>=20){soundClock=0;if(speed>.005)RailAudio.play(this,"rail_roll",(float)Math.min(.6,.1+speed*.35),(float)(.7+speed*.3));if(stock==StockType.STEAM&&temperature>100)RailAudio.play(this,"steam_exhaust",(float)(.08+speed*.2),1);else if(stock.electric()&&speed>.005)RailAudio.play(this,"electric_motor",.18f,(float)(.7+speed*.5));}}
 public void horn(){long now=worldObj.getTotalWorldTime();if(hornAt!=Long.MIN_VALUE&&now-hornAt<30)return;hornAt=now;worldObj.playSoundAtEntity(this,stock==StockType.STEAM?"industrialtech:steam_whistle":"industrialtech:train_horn",1,1);}
 public void control(EntityPlayer p,int a){if(!permitted(p)||riddenByEntity!=p)return;if(a==0){throttle=Math.min(1,throttle+.1);brake=0;}else if(a==1){throttle=Math.max(0,throttle-.1);if(throttle==0)brake=Math.min(1,brake+.2);}else if(a==2){brake=1;throttle=0;worldObj.playSoundAtEntity(this,"industrialtech:brake_air",.7f,1);}else if(a==3)horn();else if(a==4)lights=!lights;}
 @Override public boolean interactFirst(EntityPlayer p){if(p.getHeldItem()!=null&&p.getHeldItem().getItem()==RailwayRegistry.coupler){if(!worldObj.isRemote)RailCoupling.use(p,this);return true;}if(!permitted(p)&&stock!=StockType.PASSENGER)return false;if(!worldObj.isRemote){if(p.isSneaking()||!stock.engine()&&stock!=StockType.PASSENGER)p.openGui(IndustrialTechnology.instance,4,worldObj,getEntityId(),0,0);else if(riddenByEntity==null)p.mountEntity(this);}return true;}
 @Override public double getMountedYOffset(){return 1.65;}@Override public void updateRiderPosition(){if(riddenByEntity!=null){double a=Math.toRadians(rotationYaw),offset=stock==StockType.STEAM?-5:stock.engine()?stock.length*.34:0;riddenByEntity.setPosition(posX-Math.sin(a)*offset,posY+getMountedYOffset()+riddenByEntity.getYOffset(),posZ+Math.cos(a)*offset);}}
 @Override public boolean canBeCollidedWith(){return !isDead;}@Override public boolean canBePushed(){return false;}@Override public boolean attackEntityFrom(DamageSource d,float amount){if(worldObj.isRemote||!(d.getEntity() instanceof EntityPlayer))return false;EntityPlayer p=(EntityPlayer)d.getEntity();if(!p.isSneaking()||!permitted(p)||speed>.001||front!=null||rear!=null||riddenByEntity!=null)return false;ItemStack item=new ItemStack(RailwayRegistry.stockItems[stock.ordinal()]);NBTTagCompound n=new NBTTagCompound();writeEntityToNBT(n);n.removeTag("Rail");n.removeTag("Front");n.removeTag("Rear");item.setTagCompound(n);entityDropItem(item,0);setDead();return true;}
 @Override public void setDead(){tickets.release();RailwayWorld.remove(this);super.setDead();}
 @Override protected void writeEntityToNBT(NBTTagCompound n){n.setInteger("Stock",stock.ordinal());if(owner!=null)n.setString("Owner",owner.toString());if(front!=null)n.setString("Front",front.toString());if(rear!=null)n.setString("Rear",rear.toString());n.setTag("Cargo",cargo.save());n.setTag("Fuel",fuel.save());n.setInteger("RF",energy);n.setInteger("Water",water);n.setInteger("Burn",burn);n.setDouble("Temperature",temperature);n.setDouble("Travel",travel);n.setBoolean("Lights",lights);if(rail!=null){NBTTagCompound r=new NBTTagCompound();r.setString("Id",rail.track.toString());r.setInteger("Branch",rail.branch);r.setInteger("Dir",rail.direction);r.setDouble("S",rail.s);n.setTag("Rail",r);}}
 @Override protected void readEntityFromNBT(NBTTagCompound n){stock=StockType.safe(n.getInteger("Stock"));owner=uuid(n,"Owner");front=uuid(n,"Front");rear=uuid(n,"Rear");cargo.load(stock==StockType.FREIGHT?n.getTagList("Cargo",10):new NBTTagList());fuel.load(stock==StockType.STEAM?n.getTagList("Fuel",10):new NBTTagList());energy=Math.max(0,Math.min(capacity(),n.getInteger("RF")));water=Math.max(0,Math.min(30000,n.getInteger("Water")));burn=Math.max(0,Math.min(1600,n.getInteger("Burn")));temperature=finite(n.getDouble("Temperature"),20,300);travel=finite(n.getDouble("Travel"),0,1e12);lights=n.getBoolean("Lights");speed=0;brake=1;throttle=0;if(n.hasKey("Rail")){NBTTagCompound r=n.getCompoundTag("Rail");UUID id=uuid(r,"Id");if(id!=null)rail=new TrackWorld.Cursor(id,Math.max(0,Math.min(1,r.getInteger("Branch"))),finite(r.getDouble("S"),0,26),r.getInteger("Dir"));}sync();}
 public void restoreItem(ItemStack s){if(s.hasTagCompound())readEntityFromNBT(s.getTagCompound());}private static double finite(double n,double low,double high){return Double.isFinite(n)?Math.max(low,Math.min(high,n)):low;}private static UUID uuid(NBTTagCompound n,String k){try{return UUID.fromString(n.getString(k));}catch(Exception e){return null;}}
 public NBTTagCompound snapshot(){NBTTagCompound n=new NBTTagCompound();n.setString("Title",stock.title);n.setInteger("Entity",getEntityId());n.setInteger("Stock",stock.ordinal());n.setDouble("Speed",speed*72);n.setInteger("Throttle",(int)(100*throttle));n.setInteger("Brake",(int)(100*brake));n.setInteger("RF",energy);n.setInteger("Capacity",capacity());n.setInteger("Water",water);n.setInteger("Temperature",(int)temperature);n.setInteger("Wagons",consist().size()-1);n.setDouble("Mass",totalMass()/1000);n.setString("Status",status);n.setTag("Cargo",cargo.save());n.setTag("Fuel",fuel.save());n.setInteger("TotalCargo",cargo.total());n.setDouble("CargoMass",cargo.mass()/1000);return n;}
 @Override public void writeSpawnData(ByteBuf b){b.writeInt(stock.ordinal());if(rail==null)b.writeBoolean(false);else{b.writeBoolean(true);b.writeLong(rail.track.getMostSignificantBits());b.writeLong(rail.track.getLeastSignificantBits());b.writeInt(rail.branch);b.writeDouble(rail.s);b.writeInt(rail.direction);}}@Override public void readSpawnData(ByteBuf b){stock=StockType.safe(b.readInt());if(b.readBoolean())rail=new TrackWorld.Cursor(new UUID(b.readLong(),b.readLong()),b.readInt(),b.readDouble(),b.readInt());}
 @Override public void setPositionAndRotation2(double x,double y,double z,float yaw,float pitch,int ticks){targetX=x;targetY=y;targetZ=z;targetYaw=yaw;targetPitch=pitch;interpolation=Math.max(1,ticks);}
}
